 // Dead reckoning for a differential-drive base: linear speed v (m/s), angular speed w (rad/s), time step dt (s).
 Pose2D integrate_diff_drive(const Pose2D& pose, double v, double w, double dt);

+// Compose two poses: b is the relative pose in a's coordinate frame.
+Pose2D compose(const Pose2D& a, const Pose2D& b);
+
 }  // namespace amr_utils

--- a/src/amr_utils/src/odom_math.cpp
+++ b/src/amr_utils/src/odom_math.cpp
@@ -18,4 +18,14 @@
   return out;
 }

+Pose2D compose(const Pose2D& a, const Pose2D& b) {
+  Pose2D out;
+  double cos_a = std::cos(a.theta);
+  double sin_a = std::sin(a.theta);
+  out.x = a.x + cos_a * b.x - sin_a * b.y;
+  out.y = a.y + sin_a * b.x + cos_a * b.y;
+  out.theta = normalize_angle(a.theta + b.theta);
+  return out;
+}
+
 }  // namespace amr_utils

--- a/src/amr_utils/test/test_odom_math.cpp
+++ b/src/amr_utils/test/test_odom_math.cpp
@@ -28,3 +28,30 @@
   EXPECT_NEAR(p.y, 2.0, 1e-9);
   EXPECT_NEAR(p.theta, 0.5, 1e-9);
 }
+
+TEST(PoseCompose, BasicTransform) {
+  Pose2D a = {1.0, 1.0, 0.0};
+  Pose2D b = {1.0, 0.0, 0.0};
+  Pose2D res = amr_utils::compose(a, b);
+  EXPECT_NEAR(res.x, 2.0, 1e-9);
+  EXPECT_NEAR(res.y, 1.0, 1e-9);
+  EXPECT_NEAR(res.theta, 0.0, 1e-9);
+}
+
+TEST(PoseCompose, Rotation) {
+  // 有旋轉位移: a={0,0,M_PI/2}, b={1,0,0} -> {0,1,M_PI/2}
+  Pose2D a1 = {0.0, 0.0, M_PI / 2.0};
+  Pose2D b1 = {1.0, 0.0, 0.0};
+  Pose2D res1 = amr_utils::compose(a1, b1);
+  EXPECT_NEAR(res1.x, 0.0, 1e-9);
+  EXPECT_NEAR(res1.y, 1.0, 1e-9);
+  EXPECT_NEAR(res1.theta, M_PI / 2.0, 1e-9);
+
+  // 角度正規化測試: a={0,0,M_PI}, b={0,0,M_PI} -> {0,0,0}
+  Pose2D a2 = {0.0, 0.0, M_PI};
+  Pose2D b2 = {0.0, 0.0, M_PI};
+  Pose2D res2 = amr_utils::compose(a2, b2);
+  EXPECT_NEAR(res2.x, 0.0, 1e-9);
+  EXPECT_NEAR(res2.y, 0.0, 1e-9);
+  EXPECT_NEAR(res2.theta, 0.0, 1e-9);
+}

